          const ax = pt.x - hub.x, ay = pt.y - hub.y, al = Math.hypot(ax, ay) || 1;
          const away = q => { const cx = q.left + w / 2 - x, cy = q.top + h / 2 - y, cl = Math.hypot(cx, cy) || 1; return (cx * ax + cy * ay) / (cl * al); };
