        '<svg class="ic-collapse" width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M4 10h7V3M20 14h-7v7M11 10 4 3M13 14l7 7"/></svg></button>';
